import type { Capability } from "../../server/policy";

/**
 * Every agent route and the one permission it needs (phase 16, step C2; docs/SECURITY_STEP2.md):
 * the permissions matrix (`tests/permissions-matrix.test.ts`) holds every role to it. "teammate"
 * means any teammate (their own drafts, views, presence and notifications; a conversation's own
 * routes, which check the conversation itself; and read-only lists pickers need).
 *
 * A new route fails the matrix until it has a line here. `body` is a request that gets past
 * validation, for routes that check what's asked before who's asking. `restricted: false`: a
 * restricted role is refused it even though the permission is one it may have.
 */
export type RoutePolicy = { needs: Capability | "teammate"; body?: Record<string, unknown>; restricted?: false };
